// t03: purchases return and sales return day books; debit and credit notes (who issues each, and when). Imagined firms;
// every book is generated by dayBook() and asserted. No GST (removed topic: GST in the returns books).
import { mcq, ar, tf, fb, short, long } from './lib.mjs';
import { same, check, sum, inr, rs, mdTable, dayBook, Ledger, postMd, T } from './books.mjs';
import { QQ, numQ } from './qq.mjs';

// ================================================================ multiple choice
QQ('m_dn_who', mcq({
  t: 3, d: 2, c: 'understanding',
  stem: 'Jodhpur Handicrafts, an imagined firm, sends back damaged goods to its supplier and posts him a note saying that his account in its books has been debited. This note is a',
  opts: ['debit note, issued by the buyer', 'credit note, issued by the buyer', 'debit note, issued by the seller', 'credit note, issued by the seller'],
  sol: 'A debit note is sent by the buyer who returns goods, informing the supplier that his account is debited. A credit note is the seller\'s document, so the other three options mix up the document or the issuer.',
}));
QQ('m_cn_who', mcq({
  t: 3, d: 2, c: 'understanding',
  stem: 'Karimganj Tea Traders, an imagined firm, takes back goods from a customer who found them unsuitable and sends the customer a note saying that his account has been credited. The note is a',
  opts: ['credit note, issued by the seller', 'debit note, issued by the seller', 'credit note, issued by the buyer', 'debit note, issued by the buyer'],
  sol: 'The seller who accepts the goods back issues a credit note to the customer, since the customer\'s account is credited. A debit note is the buyer\'s document, and the buyer does not issue a credit note.',
}));
QQ('m_prb_post', mcq({
  t: 3, d: 2, c: 'understanding',
  stem: 'At the month end, Kendrapara Spices, an imagined firm, posts the purchases return book to the ledger. The total of the book is posted to the',
  opts: ['credit of the Purchases Return A/c, each debit note being posted to the debit of the supplier\'s account', 'debit of the Purchases Return A/c, each debit note being posted to the credit of the supplier\'s account', 'credit of the Purchases A/c, each debit note being posted to the credit of the supplier\'s account', 'credit of the Sales Return A/c, each debit note being posted to the debit of the supplier\'s account'],
  sol: 'Returning goods debits the supplier, who is owed less, and credits the Purchases Return account. The other options reverse the sides, credit the supplier, or use the account of the opposite return book.',
}));
QQ('m_chk_note', mcq({
  t: 3, d: 2, c: 'understanding',
  stem: 'Orai Pottery, an imagined firm, returns a consignment of defective jars to its supplier. The document it prepares and sends along with the goods is a',
  opts: ['debit note', 'credit note', 'pay-in slip', 'cash memo'],
  sol: 'A buyer who returns goods prepares a debit note for the supplier. A credit note is prepared by a seller, a pay-in slip is a bank form, and a cash memo records a cash sale.',
}));
QQ('m_return_book_which', mcq({
  t: 3, d: 2, c: 'understanding',
  stem: 'Hailakandi Paints, an imagined firm, takes back goods sold on credit to a dealer and issues him a credit note. The first book of record for this transaction is the',
  opts: ['sales return book', 'purchases return book', 'sales book', 'journal proper'],
  sol: 'Goods taken back from a customer are recorded in the sales return book. The purchases return book is for goods sent back to a supplier, the sales book records outward sales, and the journal proper is used only when no special book exists.',
}));
const RN = 3000 - Math.round((3000 * 20) / 100);
same(RN, 2400, 'm_ret_net');
QQ('m_ret_net', mcq({
  t: 3, d: 3, c: 'application',
  stem: 'Aizawl Bamboo Works, an imagined firm, bought goods at a list price of ₹15,000 with trade discount of 20%. Goods of list price ₹3,000 are returned. The amount of the debit note, entered in the purchases return book, is',
  opts: [rs(RN), rs(3000), rs(600), rs(12000)],
  sol: `Net value of the returned goods = ${inr(3000)} − ${inr(600)} = ${rs(RN)}, since the same 20% discount applies. The ${rs(3000)} ignores the discount, ${rs(600)} is the discount alone, and ${rs(12000)} is the net value of the whole purchase.`,
}));

// ================================================================ assertion-reason
QQ('ar_dn_cn', ar({
  t: 3, d: 3, c: 'analysis', verdict: 'both-true-not-explains',
  a: 'A buyer who returns goods to a supplier sends him a debit note.',
  r: 'The sales return book of the supplier is written from the credit notes that he issues.',
  sol: 'Both statements are true, but the second describes the seller\'s book and has no bearing on why the buyer sends a debit note.',
}));
QQ('ar_return_false', ar({
  t: 3, d: 4, c: 'evaluation', verdict: 'both-false',
  a: 'Goods returned by a customer to Shivpuri Stationers, an imagined firm, are entered in its sales book as a negative item.',
  r: 'A credit note is a document sent by the customer to the seller when he returns the goods.',
  sol: 'Both are false: such returns have a sales return book of their own, and the credit note is issued by the seller, not the customer.',
}));

// ================================================================ true-false, fill-blank
QQ('tf_return_cash', tf({
  t: 3, d: 2, c: 'understanding', ans: false,
  stem: 'Namrup Textiles, an imagined firm, returns goods to a supplier and receives the money in cash on the same day. The transaction is recorded in the purchases return book.',
  sol: 'The purchases return book is for returns that reduce the amount owed to a supplier. A return for which cash is received at once is a cash transaction and goes to the cash book.',
}));
QQ('fb_dn_issuer', fb({
  t: 3, d: 1, c: 'recall',
  stem: 'A ______ note is sent by a buyer to a supplier when goods are sent back, while a ______ note is sent by a seller to a customer when goods are taken back.',
  acc: [['debit'], ['credit']],
  sol: 'The buyer sends the debit note and the seller the credit note.',
}));

// ================================================================ numerical
const R1 = dayBook({ kind: 'purchaseReturns', entries: [T('1', '1', 'A', 8000, 10), T('2', '2', 'B', 5500, 0), T('3', '3', 'C', 12000, 20)] });
same(R1.totals.net, 7200 + 5500 + 9600, 'n_prb_total');
QQ('n_prb_total', numQ({
  t: 3, d: 3, c: 'application', value: R1.totals.net,
  stem: 'Sirsa Auto Parts, an imagined firm, sent three debit notes in a month for goods returned to its suppliers: list price ₹8,000 with trade discount 10%; list price ₹5,500 without discount; and list price ₹12,000 with trade discount 20%. The amount posted to the credit of its Purchases Return A/c is (in ₹)',
  sol: `Notes = ${inr(7200)} + ${inr(5500)} + ${inr(9600)} = ${rs(R1.totals.net)}, the first and third being net of discounts of ${inr(800)} and ${inr(2400)}.`,
}));
const R2 = new Ledger().open('Karan Opticals A/c', 'dr', 12000, '1 Mar').fromBook(dayBook({ kind: 'sales', entries: [T('6 Mar', '1', 'Karan Opticals', 30000, 10)] }), '31 Mar').fromBook(dayBook({ kind: 'salesReturns', entries: [T('20 Mar', '1', 'Karan Opticals', 5000, 10)] }), '31 Mar');
same(R2.balance('Karan Opticals A/c'), 12000 + 27000 - 4500, 'n_srb_account');
QQ('n_srb_account', numQ({
  t: 3, d: 3, c: 'application', value: 34500,
  stem: 'Karan Opticals owed Jammu Optics, an imagined firm, ₹12,000 on 1 March. On 6 March the firm sold it goods on credit at a list price of ₹30,000 less trade discount of 10%, and on 20 March it took back goods of list price ₹5,000 for which the same discount had been given, and issued a credit note. The balance in the account of Karan Opticals on 31 March is (in ₹)',
  sol: `Debit side = ${inr(12000)} + ${inr(27000)} = ${inr(39000)}; credit side = ${inr(4500)}; balance = ${inr(39000)} − ${inr(4500)} = ${rs(34500)}, a debit balance.`,
}));

// ================================================================ short answer, 2 marks
QQ('s2_dn_cn_distinguish', short({
  t: 3, d: 2, c: 'understanding', marks: 2,
  stem: 'Distinguish a debit note from a credit note on the basis of who issues it and when.',
  model: mdTable(['Basis', 'Debit note', 'Credit note'], [['Issued by', 'The buyer', 'The seller'], ['When', 'When goods are returned to the supplier', 'When goods are taken back from the customer']]),
  sol: 'One mark for each document, with issuer and occasion.',
  scheme: [['Debit note: issued by the buyer when he returns goods', 1], ['Credit note: issued by the seller when he takes goods back', 1]],
}));
QQ('s2_return_reasons', short({
  t: 3, d: 2, c: 'understanding', marks: 2,
  stem: 'State two reasons for which an imagined retailer may send goods back to its supplier, and name the book in which the return is recorded.',
  model: 'Reasons: the goods are damaged or defective; the goods differ from the quality or quantity ordered (or arrive late and are no longer needed).\n\nThe return is entered in the purchases return book, using the debit note.',
  sol: 'One mark for two reasons and one mark for the book.',
  scheme: [['Two reasons for the return given', 1], ['Purchases return book (debit note) named', 1]],
}));
QQ('s2_return_effect', short({
  t: 3, d: 3, c: 'application', marks: 2,
  stem: 'Ghazipur Brass, an imagined firm, returns goods worth ₹6,000 (net of trade discount) to a supplier, Mirzapur Metals. State the account debited and the account credited in the ledger of Ghazipur Brass, and the effect on the amount payable to Mirzapur Metals.',
  model: 'Debit: the account of Mirzapur Metals (₹6,000). Credit: Purchases Return A/c (₹6,000). The amount payable to Mirzapur Metals falls by ₹6,000.',
  sol: 'Debit, credit and effect.',
  scheme: [['Mirzapur Metals debited and Purchases Return A/c credited with ₹6,000', 1], ['Amount payable to the supplier reduced by ₹6,000', 1]],
}));

// ================================================================ short answer, 3 marks
const PR3 = dayBook({ kind: 'purchaseReturns', entries: [T('7 Jun', '1', 'Shimla Knits', 12000, 10), T('15 Jun', '2', 'Chamba Yarns', 9500, 20), T('24 Jun', '3', 'Shimla Knits', 6000, 10)] });
same(PR3.totals.net, 10800 + 7600 + 5400, 's3_prb_book');
QQ('s3_prb_book', short({
  t: 3, d: 3, c: 'application', marks: 3,
  stem: 'Almora Woollens, an imagined firm, sent debit notes for goods returned in June 2028: 7 Jun, note 1, Shimla Knits, list price ₹12,000, trade discount 10%; 15 Jun, note 2, Chamba Yarns, list price ₹9,500, trade discount 20%; 24 Jun, note 3, Shimla Knits, list price ₹6,000, trade discount 10%. Prepare the purchases return book and show its posting.',
  model: `${PR3.md}\n\n${postMd(PR3)}\n\nThe total ${rs(PR3.totals.net)} is credited to Purchases Return A/c and each debit note is debited to the supplier's account.`,
  sol: 'Net value of each note, the book total and the posting summary.',
  scheme: [['Each note entered at net value (₹10,800, ₹7,600, ₹5,400)', 1], ['Book totalled at ₹23,800', 1], ['Suppliers debited and Purchases Return A/c credited with ₹23,800', 1]],
}));
const SR3 = dayBook({ kind: 'salesReturns', entries: [T('10 Aug', '1', 'Meghna Stores', 8000, 10), T('20 Aug', '2', 'Ojas Mart', 4500, 0), T('29 Aug', '3', 'Meghna Stores', 3000, 5)] });
same(SR3.totals.net, 7200 + 4500 + 2850, 's3_srb_book');
QQ('s3_srb_book', short({
  t: 3, d: 3, c: 'application', marks: 3,
  stem: 'Raigarh Kitchenware, an imagined firm, accepted goods back from customers in August 2028 and issued credit notes: 10 Aug, note 1, Meghna Stores, list price ₹8,000, trade discount 10%; 20 Aug, note 2, Ojas Mart, list price ₹4,500, no discount; 29 Aug, note 3, Meghna Stores, list price ₹3,000, trade discount 5%. Prepare the sales return book and show how it is posted.',
  model: `${SR3.md}\n\n${postMd(SR3)}\n\nThe total ${rs(SR3.totals.net)} is debited to Sales Return A/c and each credit note is credited to the customer's account.`,
  sol: 'Net value of each credit note, the book total and the posting summary.',
  scheme: [['Each credit note entered at net value (₹7,200, ₹4,500, ₹2,850)', 1], ['Book totalled at ₹14,550', 1], ['Sales Return A/c debited and the customers credited with ₹14,550', 1]],
}));
const RA = new Ledger().open('Raman Pipes A/c', 'cr', 20000, '1 Mar')
  .fromBook(dayBook({ kind: 'purchases', entries: [T('5 Mar', '18', 'Raman Pipes', 35000, 0), T('18 Mar', '24', 'Raman Pipes', 27500, 5)] }), '31 Mar')
  .fromBook(dayBook({ kind: 'purchaseReturns', entries: [T('9 Mar', '1', 'Raman Pipes', 4000, 0), T('25 Mar', '2', 'Raman Pipes', 2500, 5)] }), '31 Mar');
const RAM = RA.show('Raman Pipes A/c', { close: '31 Mar', next: '1 Apr' });
same(RAM.balance, -(20000 + 35000 + 26125 - 4000 - 2375), 's3_return_account');
QQ('s3_return_account', short({
  t: 3, d: 3, c: 'application', marks: 3,
  stem: 'Nanjangud Plumbing, an imagined firm, owed Raman Pipes ₹20,000 on 1 March. During March it bought goods on credit: 5 Mar, invoice 18, list price ₹35,000, no discount; 18 Mar, invoice 24, list price ₹27,500, trade discount 5%. It returned goods (debit notes): 9 Mar, note 1, list price ₹4,000, no discount; 25 Mar, note 2, list price ₹2,500, trade discount 5%. Write the account of Raman Pipes in the ledger of Nanjangud Plumbing and balance it on 31 March.',
  model: `${RAM.md}\n\nThe credit balance of ${rs(-RAM.balance)} is the amount still payable to Raman Pipes.`,
  sol: 'Opening balance and net purchases on the credit side, returns on the debit side, then the balance.',
  scheme: [['Opening balance and the two purchases at net amounts on the credit side', 1], ['The two returns at net amounts on the debit side', 1], ['Balance ₹74,750 carried down and brought down with equal totals', 1]],
}));

// ================================================================ long answer, 5 marks
const SV = {
  prb: dayBook({ kind: 'purchaseReturns', entries: [T('6 Nov', '1', 'Dibrugarh Cables', 14000, 10), T('18 Nov', '2', 'Tinsukia Switches', 8000, 5), T('26 Nov', '3', 'Dibrugarh Cables', 5500, 0)] }),
  srb: dayBook({ kind: 'salesReturns', entries: [T('9 Nov', '1', 'Lakhimpur Stores', 6000, 10), T('22 Nov', '2', 'Golaghat Traders', 12500, 20), T('29 Nov', '3', 'Lakhimpur Stores', 4000, 0)] }),
};
same(SV.prb.totals.net, 12600 + 7600 + 5500, 'Sivasagar purchases return');
same(SV.srb.totals.net, 5400 + 10000 + 4000, 'Sivasagar sales return');
const NETP = 310000 - SV.prb.totals.net;
const NETS = 425000 - SV.srb.totals.net;
same(NETP, 284300, 'Sivasagar net purchases');
same(NETS, 405600, 'Sivasagar net sales');
QQ('l5_returns_both', long({
  t: 3, d: 4, c: 'application', marks: 5,
  stem: 'Sivasagar Electricals, an imagined firm, had credit purchases of ₹3,10,000 and credit sales of ₹4,25,000 in November 2028, both net of trade discount. It sent these debit notes (list price, trade discount): 6 Nov, note 1, Dibrugarh Cables, ₹14,000, 10%; 18 Nov, note 2, Tinsukia Switches, ₹8,000, 5%; 26 Nov, note 3, Dibrugarh Cables, ₹5,500, nil. It issued these credit notes: 9 Nov, note 1, Lakhimpur Stores, ₹6,000, 10%; 22 Nov, note 2, Golaghat Traders, ₹12,500, 20%; 29 Nov, note 3, Lakhimpur Stores, ₹4,000, nil. (a) Prepare the purchases return book [2]. (b) Prepare the sales return book [2]. (c) Find the net purchases and the net sales for the month [1].',
  model: `**(a)**\n\n${SV.prb.md}\n\n**(b)**\n\n${SV.srb.md}\n\n**(c)** Net purchases = ${inr(310000)} − ${inr(SV.prb.totals.net)} = **${rs(NETP)}**; net sales = ${inr(425000)} − ${inr(SV.srb.totals.net)} = **${rs(NETS)}**.`,
  sol: 'Net value of each note, the two book totals, then the deductions from purchases and sales.',
  scheme: [['Debit notes entered at the net values ₹12,600, ₹7,600 and ₹5,500', 1], ['Purchases return book totalled at ₹25,700', 1], ['Credit notes entered at the net values ₹5,400, ₹10,000 and ₹4,000', 1], ['Sales return book totalled at ₹19,400', 1], ['Net purchases ₹2,84,300 and net sales ₹4,05,600', 1]],
}));
